import { createContext, useContext } from "react";
import { dinheiro } from "../format";
import type { AlvoRastro } from "./Rastro";

export const RastroContext = createContext<(alvo: AlvoRastro) => void>(() => {});

/** Todo valor de saída é clicável e abre o rastro dele. */
export function Valor({ id, valor, titulo, forte }: { id: string; valor: string | null; titulo: string; forte?: boolean }) {
  const abrir = useContext(RastroContext);
  return (
    <button
      onClick={() => valor != null && abrir({ id, valor, titulo })}
      className={`num rounded px-1 -mx-1 text-right underline decoration-linha-forte decoration-dotted underline-offset-4 transition-colors hover:bg-decisao-fundo hover:decoration-decisao ${forte ? "font-semibold" : ""}`}
      title="Ver de onde vem esse número"
    >
      {dinheiro(valor)}
    </button>
  );
}

"""API do painel. Não tem regra de negócio: chama `run_closing`, lê a saída e grava condições
comerciais pelo módulo `tarvo.condicoes` (que valida). Valores monetários saem como texto."""

from __future__ import annotations

import datetime as dt
import fnmatch
import logging
import math
from decimal import Decimal
from pathlib import Path
from typing import Annotated, Any

import pandas as pd
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from tarvo import condicoes as cond_mod
from tarvo import rules, sinais
from tarvo.avaliacao import avaliar_e_persistir
from tarvo.loaders import ESPERADOS, FILES, OPCIONAIS, load_all
from tarvo.loaders.identificar import classificar_lote
from tarvo.orquestrador import ClosingResult, run_closing

log = logging.getLogger("tarvo.web")
STATIC = Path(__file__).resolve().parent / "static"
FIXTURES = Path(__file__).resolve().parents[3] / "tests" / "fixtures"
LIMITE_UPLOAD = 20 * 1024 * 1024
PADROES_ACEITOS = [*FILES.values(), *OPCIONAIS.values(), "00_LEIA-ME*"]


def _json(valor: Any) -> Any:
    if isinstance(valor, Decimal):
        return str(valor)
    if isinstance(valor, dt.date):
        return valor.isoformat()
    if isinstance(valor, float) and math.isnan(valor):
        return None
    if valor is pd.NaT or valor is None:
        return None
    return valor


def _registros(df: pd.DataFrame) -> list[dict]:
    if df is None or df.empty:
        return []
    return [{k: _json(v) for k, v in linha.items()} for linha in df.to_dict("records")]


def _soma(df: pd.DataFrame, coluna: str, filtro=None) -> str:
    if df.empty:
        return "0.00"
    alvo = df[filtro(df)] if filtro is not None else df
    return str(sum((Decimal(str(v)) for v in alvo[coluna]), Decimal("0.00")))


def _totais(r: ClosingResult) -> dict:
    com, div = r.comissoes, r.divergencias

    def prefixo(p: str):
        return lambda d: d["id_saida"].str.startswith(p)

    return {
        "comissao_checkout": _soma(com, "comissao_brl", lambda d: d["linha_negocio"] == "CHECKOUT"),
        "comissao_remessa": _soma(com, "comissao_brl", lambda d: d["linha_negocio"] == "REMESSA"),
        "cobrar_orbe": _soma(div, "diferenca_brl", prefixo("CK-DIV")),
        "devolver_condicao": _soma(div, "diferenca_brl", prefixo("CK-COND")),
        "divergencia_remessa": _soma(div, "diferenca_brl", prefixo("RM-DIV")),
        "notas": _soma(r.notas, "valor_brl"),
    }


def _arquivos(dados: Path) -> list[dict]:
    achados = []
    for padrao in PADROES_ACEITOS:
        for f in sorted(dados.glob(padrao)):
            achados.append({"nome": f.name, "bytes": f.stat().st_size,
                            "opcional": any(fnmatch.fnmatch(f.name, p) for p in OPCIONAIS.values())})
    return achados


def criar_app(dados: Path, saida: Path, condicoes_path: Path | None = None) -> FastAPI:
    app = FastAPI(title="Tarvo · Fechamento", docs_url="/api/docs")
    app.state.dados = Path(dados)
    app.state.saida = Path(saida)
    app.state.condicoes = condicoes_path or cond_mod.CAMINHO_PADRAO
    app.state.resultado = None
    app.state.avaliacao = None

    def fechar() -> ClosingResult:
        try:
            r = run_closing(app.state.dados, app.state.saida, condicoes_path=app.state.condicoes)
        except (FileNotFoundError, ValueError, KeyError) as exc:
            log.exception("falha no fechamento")
            raise HTTPException(
                400, f"Não foi possível fechar com os arquivos de {app.state.dados}: {exc}"
            ) from exc
        app.state.resultado = r
        app.state.avaliacao = avaliar_e_persistir(r, fixtures_dir=FIXTURES, saida=app.state.saida) \
            if FIXTURES.exists() else None
        return r

    def resultado() -> ClosingResult:
        return app.state.resultado or fechar()

    def resposta(r: ClosingResult) -> dict:
        aval = (app.state.avaliacao or {}).get("resumo")
        return {
            "competencia": r.competencia,
            "execucao_id": r.execucao_id,
            "pasta_saida": str(r.out_dir),
            "regras_versao": rules.VERSION,
            "duracao_s": r.duracoes_s.get("total"),
            "arquivos": _arquivos(app.state.dados),
            "validacoes": {
                "rastro_ok": r.problemas_rastro.empty,
                "integridade_ok": not r.problemas_integridade,
                "problemas": [str(p) for p in r.problemas_integridade][:20],
                "referencia": aval,
            },
            "totais": _totais(r),
            "tabelas": {nome: _registros(getattr(r, nome)) for nome in
                        ("comissoes", "divergencias", "notas", "lancamentos", "pendencias")},
        }

    @app.get("/api/fechamento")
    def get_fechamento() -> dict:
        return resposta(resultado())

    @app.post("/api/fechar")
    def post_fechar() -> dict:
        return resposta(fechar())

    @app.get("/api/rastro/{id_saida}")
    def get_rastro(id_saida: str) -> dict:
        rastro = resultado().rastro
        linhas = rastro[rastro["id_saida"] == id_saida]
        if linhas.empty:
            raise HTTPException(404, f"Sem rastro para {id_saida}")
        return {"id_saida": id_saida, "linhas": _registros(linhas)}

    @app.get("/api/lojistas")
    def get_lojistas() -> list[dict]:
        taxas = load_all(app.state.dados)["taxas"]
        unicos = taxas.drop_duplicates("cnpj")[["cnpj", "lojista"]]
        return [{"cnpj": c, "lojista": str(n).strip()} for c, n in unicos.itertuples(index=False)]

    @app.get("/api/condicoes")
    def get_condicoes() -> dict:
        bruto = cond_mod._ler_arquivo(app.state.condicoes)
        return {"condicoes": bruto.get("condicoes", []),
                "sinais_resolvidos": bruto.get("sinais_resolvidos", [])}

    @app.post("/api/condicoes", status_code=201)
    def post_condicao(corpo: dict) -> dict:
        try:
            registro = cond_mod.registrar_condicao(app.state.condicoes, corpo)
        except (ValueError, TypeError) as exc:
            raise HTTPException(422, str(exc)) from exc
        return {"condicao": registro, "fechamento": resposta(fechar())}

    @app.post("/api/sinais-resolvidos", status_code=201)
    def post_sinal_resolvido(corpo: dict) -> dict:
        try:
            registro = cond_mod.registrar_sinal_resolvido(app.state.condicoes, corpo)
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc
        return {"sinal": registro, "fechamento": resposta(fechar())}

    @app.get("/api/sinais")
    def get_sinais() -> list[dict]:
        r = resultado()
        taxas = load_all(app.state.dados)["taxas"]
        conds = cond_mod.carregar(app.state.condicoes)
        resolvidos = cond_mod.carregar_sinais_resolvidos(app.state.condicoes)
        return [{"id_saida": pid, "cnpj": m.sinal.cnpj, "lojista": m.sinal.lojista, "linha": m.sinal.linha,
                 "campo": m.sinal.campo, "texto": m.sinal.texto, "metodo": m.metodo}
                for m, pid in sinais.abertos(taxas, r.competencia, conds, resolvidos)]

    @app.get("/api/arquivos-esperados")
    def get_arquivos_esperados() -> list[dict]:
        return ESPERADOS

    async def _ler(arquivos: list[UploadFile]) -> list[tuple[str, bytes]]:
        lidos = []
        for a in arquivos:
            conteudo = await a.read()
            nome = Path(a.filename or "").name
            if len(conteudo) > LIMITE_UPLOAD:
                raise HTTPException(413, f"{nome} passa de 20 MB")
            lidos.append((nome, conteudo))
        return lidos

    @app.post("/api/arquivos/conferir")
    async def post_conferir(arquivos: Annotated[list[UploadFile], File()]) -> dict:
        """Só confere (não grava nem fecha): a tela mostra o que foi reconhecido e o que falta."""
        return classificar_lote(await _ler(arquivos))

    @app.post("/api/arquivos")
    async def post_arquivos(arquivos: Annotated[list[UploadFile], File()]) -> dict:
        lidos = await _ler(arquivos)
        lote = classificar_lote(lidos)
        if lote["problemas"]:
            raise HTTPException(422, "Envie exatamente os 6 arquivos do mês. " + "; ".join(lote["problemas"]))
        destino = app.state.saida / "entradas" / dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        destino.mkdir(parents=True, exist_ok=True)
        canonicos = {i["nome"]: i["nome_canonico"] for i in lote["arquivos"]}
        for nome, conteudo in lidos:
            if canonicos.get(nome):
                (destino / canonicos[nome]).write_bytes(conteudo)
        app.state.dados = destino
        return resposta(fechar())

    if (STATIC / "index.html").exists():
        app.mount("/assets", StaticFiles(directory=STATIC / "assets"), name="assets")

        @app.get("/{caminho:path}", include_in_schema=False)
        def front(caminho: str) -> FileResponse:
            return FileResponse(STATIC / "index.html")

    return app

"""Reconhece cada arquivo do mês: primeiro pelo padrão de nome; se o nome não bater (arquivo
renomeado, "relatorio (1).csv"), pela assinatura do conteúdo. Ajustes da Orbe têm o mesmo formato
do relatório principal, então só são reconhecidos pelo nome (R34: avisar o que quebra)."""

from __future__ import annotations

import io
import zipfile
from fnmatch import fnmatch

from tarvo.loaders import ESPERADOS, IGNORADOS

ORBE_CABECALHO = "id_transacao;data_movimento;cod_estabelecimento"
AURORA_CABECALHO = "Data;Lançamento;Documento;Valor (R$);Saldo (R$)"


def _texto(conteudo: bytes, limite: int = 4096) -> str:
    trecho = conteudo[:limite]
    try:
        return trecho.decode("utf-8")
    except UnicodeDecodeError:
        return trecho.decode("latin-1")


def _abas_xlsx(conteudo: bytes) -> str:
    """Texto do workbook.xml (nomes das abas) sem abrir a planilha inteira."""
    try:
        with zipfile.ZipFile(io.BytesIO(conteudo)) as z:
            return z.read("xl/workbook.xml").decode("utf-8", "replace")
    except (zipfile.BadZipFile, KeyError):
        return ""


def _por_conteudo(conteudo: bytes) -> str | None:
    texto = _texto(conteudo)
    if texto.startswith(ORBE_CABECALHO):
        return "orbe"
    if texto.startswith("COD_CONTA;"):
        return "plano"
    if AURORA_CABECALHO in texto:
        return "aurora"
    if "OFXHEADER" in texto or "<STMTTRN>" in _texto(conteudo, 65536):
        return "meridiano"
    if conteudo[:2] == b"PK" and "Taxas vigentes" in _abas_xlsx(conteudo):
        return "taxas"
    if ("MIME-Version" in texto or "Content-Type" in texto) and b".xlsx" in conteudo:
        return "ponte"
    return None


def identificar(nome: str, conteudo: bytes) -> tuple[str, str] | None:
    """(chave do arquivo, "nome" | "conteudo") ou None se não é um arquivo do fechamento."""
    for e in ESPERADOS:
        if fnmatch(nome, e["padrao"]):
            return e["chave"], "nome"
    chave = _por_conteudo(conteudo)
    return (chave, "conteudo") if chave else None


def _canonico(chave: str, indice: int, original: str) -> str:
    extensao = original.rsplit(".", 1)[-1].lower() if "." in original else "csv"
    if chave == "orbe_ajustes":
        return f"06_orbe_ajustes_enviado{indice + 1}.{extensao}"
    padrao = next(e["padrao"] for e in ESPERADOS if e["chave"] == chave)
    return padrao.replace("*", "_enviado" if padrao.endswith("*.xlsx") else "enviado", 1)


def classificar_lote(arquivos: list[tuple[str, bytes]]) -> dict:
    """Classifica um lote de upload: cada arquivo com a chave e o nome com que será gravado,
    e a lista de problemas (obrigatório faltando ou repetido, arquivo que não é do fechamento)."""
    itens, problemas, contagem = [], [], {}
    for nome, conteudo in arquivos:
        if any(fnmatch(nome, p) for p in IGNORADOS):
            continue
        achado = identificar(nome, conteudo)
        if achado is None:
            problemas.append(f"{nome}: não é um arquivo do fechamento")
            itens.append({"nome": nome, "chave": None, "por": None, "nome_canonico": None})
            continue
        chave, por = achado
        indice = contagem.get(chave, 0)
        contagem[chave] = indice + 1
        canonico = nome if por == "nome" else _canonico(chave, indice, nome)
        itens.append({"nome": nome, "chave": chave, "por": por, "nome_canonico": canonico})
    for e in (e for e in ESPERADOS if e["obrigatorio"]):
        achados = [i["nome"] for i in itens if i["chave"] == e["chave"]]
        if not achados:
            problemas.append(f"faltando: {e['nome']} ({e['padrao']})")
        elif len(achados) > 1:
            problemas.append(f"mais de um {e['nome']}: {', '.join(achados)}")
    return {"arquivos": itens, "problemas": problemas}

import { useMemo, useState } from "react";
import type { Fechamento, Linha } from "../api";
import { cnpj, data, dinheiro, pct } from "../format";
import { nomesPorCnpj } from "./Pendencias";
import { Valor } from "./Valor";

const th = "py-2.5 pr-4 text-left text-xs font-medium text-tinta-3";
const td = "py-2 pr-4";

function Filtros<T extends string>({ opcoes, atual, aoMudar }: { opcoes: [T, string, number][]; atual: T; aoMudar: (v: T) => void }) {
  return (
    <div role="tablist" className="mb-4 flex flex-wrap gap-1.5">
      {opcoes.map(([v, nome, n]) => (
        <button
          key={v}
          role="tab"
          aria-selected={atual === v}
          onClick={() => aoMudar(v)}
          className={`rounded-full border px-3 py-1 text-sm transition-colors ${
            atual === v ? "border-tinta bg-tinta text-folha" : "border-linha-forte text-tinta-2 hover:bg-folha"
          }`}
        >
          {nome} <span className={atual === v ? "text-folha/70" : "text-tinta-3"}>{n}</span>
        </button>
      ))}
    </div>
  );
}

/** Faixa de razão: os totais do mês em uma linha, como no rodapé de um livro contábil. */
export function Razao({ f }: { f: Fechamento }) {
  const t = f.totais;
  const itens: [string, string, string][] = [
    ["Comissão checkout", t.comissao_checkout, "a faturar dos lojistas"],
    ["Comissão remessa", t.comissao_remessa, "nota única para a Ponte"],
    ["Notas a emitir", t.notas, `${f.tabelas.notas.length} notas`],
    ["Cobrar da Orbe", t.cobrar_orbe, "taxa diferente do contrato"],
    ["Devolver ao lojista", t.devolver_condicao, "condição comercial não avisada"],
    ["Contestar com a Ponte", t.divergencia_remessa, "spread acima do contrato"],
  ];
  return (
    <dl className="grid grid-cols-2 border-y border-linha-forte md:grid-cols-3 xl:grid-cols-6">
      {itens.map(([nome, valor, nota]) => (
        <div key={nome} className="border-linha py-4 pr-4 [&:not(:last-child)]:border-r md:pl-4 md:first:pl-0">
          <dt className="text-xs text-tinta-3">{nome}</dt>
          <dd className="num mt-1 text-lg font-semibold">{dinheiro(valor)}</dd>
          <dd className="text-xs text-tinta-3">{nota}</dd>
        </div>
      ))}
    </dl>
  );
}

export function Numeros({ f }: { f: Fechamento }) {
  const [linha, setLinha] = useState<"CHECKOUT" | "REMESSA">("CHECKOUT");
  const com = f.tabelas.comissoes
    .filter((c) => c.linha_negocio === linha)
    .sort((a, b) => Number(b.comissao_brl) - Number(a.comissao_brl));
  const notas = f.tabelas.notas;
  return (
    <div className="space-y-10">
      <Razao f={f} />
      <div className="grid gap-10 xl:grid-cols-[3fr_2fr]">
        <section>
          <h2 className="mb-3 text-[15px] font-semibold">Comissão por lojista</h2>
          <Filtros
            opcoes={[
              ["CHECKOUT", "Checkout", f.tabelas.comissoes.filter((c) => c.linha_negocio === "CHECKOUT").length],
              ["REMESSA", "Remessa", f.tabelas.comissoes.filter((c) => c.linha_negocio === "REMESSA").length],
            ]}
            atual={linha}
            aoMudar={setLinha}
          />
          <table className="w-full text-sm">
            <thead className="border-b border-linha-forte">
              <tr>
                <th className={th}>Lojista</th>
                <th className={th}>CNPJ</th>
                <th className={`${th} text-right`}>Comissão</th>
              </tr>
            </thead>
            <tbody>
              {com.map((c) => (
                <tr key={c.id_saida} className="border-b border-linha">
                  <td className={td}>{c.lojista}</td>
                  <td className={`${td} num text-tinta-2`}>{cnpj(c.cnpj)}</td>
                  <td className={`${td} pr-0 text-right`}>
                    <Valor id={c.id_saida!} valor={c.comissao_brl} titulo={`Comissão ${linha.toLowerCase()} · ${c.lojista}`} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
        <section>
          <h2 className="mb-3 text-[15px] font-semibold">Notas a emitir</h2>
          <p className="mb-4 text-sm text-tinta-2">Uma por lojista no checkout; uma única para a Ponte na remessa. Saldo zero ou negativo não emite.</p>
          <table className="w-full text-sm">
            <thead className="border-b border-linha-forte">
