                  <td className={td}>
                    {n.tomador}
                    {n.linha_negocio === "REMESSA" && <span className="ml-2 text-xs text-tinta-3">remessa</span>}
                  </td>
                  <td className={`${td} pr-0 text-right`}>
                    <Valor id={n.id_saida!} valor={n.valor_brl} titulo={`Nota · ${n.tomador}`} />
                  </td>
