                className="fixed bottom-6 left-1/2 z-50 -translate-x-1/2 rounded-lg bg-tinta px-4 py-2.5 text-sm text-folha shadow-[0_8px_24px_-8px_oklch(0.24_0.02_255/0.4)]"
              >
                {aviso}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </RastroContext.Provider>
